        T* pCurr = NULL;
        T v(0);
        // #pragma omp parallel for default(none) private(c, r) shared(COL, ROW, pRes) if ( COL > 16 )
        for ( c=0; c<(long long)COL; c++ )
        {
            v = 0;
            pCurr = this->data_ + c*ROW;
            for ( r=0; r<ROW; r++ )
            {
                v += pCurr[r];
            }
            pRes[c] = v;
        }

        //size_t r, c;
        //for ( c=0; c<COL; c++ )
        //{
        //    T v = (*this)(0, c);
        //    for ( r=1; r<ROW; r++ )
        //    {
        //        v += (*this)(r, c);
        //        //v += this->data_[r+c*ROW];
        //    }
        //    res(c) = v;
