// Pointer version calls the reference version
template <typename T, class S>
void subtract(const hoNDArray<T>* x, const hoNDArray<S>* y, hoNDArray<typename mathReturnType<T,S>::type >* r)
{
  subtract(*x, *y, *r);
}


