/** \file twoParaExpDecayOperator.h
    \brief Implement two parameter exponential decay operator.
    \author     Hui Xue
*/



// ===== Begin: toolboxes/operators/curveFittingOperator.h =====
/** \file curveFittingOperator.h
    \brief Base class for all operators for curve fitting purpose.
    \author     Hui Xue
*/



namespace Gadgetron {

    template <class ARRAY> class curveFittingOperator
    {
    public:

        typedef curveFittingOperator<ARRAY> Self;
        typedef typename ARRAY::value_type ELEMENT_TYPE;
        typedef typename realType<ELEMENT_TYPE>::Type REAL;

        curveFittingOperator();
        virtual ~curveFittingOperator();

        /// Calculates the gradient of the operator at point xi with parameter bi
        virtual void gradient(const ELEMENT_TYPE& xi, const ARRAY& b, ARRAY& grad) = 0;

        /// evaluate the operator at parameter bi for every xi
        virtual void magnitude(const ARRAY& x, const ARRAY& b, ARRAY& y) = 0;

    protected:
    };

    template <class ARRAY>
    curveFittingOperator<ARRAY>::curveFittingOperator()
    {
    }

    template <class ARRAY>
    curveFittingOperator<ARRAY>::~curveFittingOperator()
    {
    }
}
// ===== End: toolboxes/operators/curveFittingOperator.h =====


namespace Gadgetron {

    // y = bi[0] * exp(-x/bi[1])

    template <class ARRAY> class twoParaExpDecayOperator : public curveFittingOperator<ARRAY>
    {
    public:

        typedef curveFittingOperator<ARRAY> BaseClass;
        typedef typename BaseClass::ELEMENT_TYPE ELEMENT_TYPE;
        typedef typename BaseClass::REAL REAL;

        twoParaExpDecayOperator();
        virtual ~twoParaExpDecayOperator();

        virtual void gradient(const ELEMENT_TYPE& xi, const ARRAY& b, ARRAY& grad);
        virtual void magnitude(const ARRAY& x, const ARRAY& b, ARRAY& y);

    protected:
    };

    template <class ARRAY>
    twoParaExpDecayOperator<ARRAY>::twoParaExpDecayOperator() : BaseClass()
    {
    }

    template <class ARRAY>
    twoParaExpDecayOperator<ARRAY>::~twoParaExpDecayOperator()
    {
    }

    template <class ARRAY>
    void twoParaExpDecayOperator<ARRAY>::gradient(const ELEMENT_TYPE& xi, const ARRAY& b, ARRAY& grad)
    {
        try
        {
            size_t num = b.size();
            if(grad.size()!=num) grad.resize(num, 0);

            int sign_b1 = boost::math::sign(b[1]);
            ELEMENT_TYPE rb = 1.0 / ( (std::abs(b[1])<FLT_EPSILON) ? sign_b1*FLT_EPSILON : b[1] );

            ELEMENT_TYPE val = std::exp(-1 * xi * rb);
            grad[0] = val;
            grad[1] = b[0] * val * xi * rb * rb;
        }
        catch(...)
        {
            GADGET_THROW("Errors happened in twoParaExpDecayOperator<ARRAY>::gradient(...) ... ");
        }
    }

    template <class ARRAY>
    void twoParaExpDecayOperator<ARRAY>::magnitude(const ARRAY& x, const ARRAY& b, ARRAY& y)
    {
        size_t num = x.size();
        if(y.size()!=x.size()) y.resize(num, 0);

        int sign_b1 = boost::math::sign(b[1]);
        ELEMENT_TYPE rb = 1.0 / ( (std::abs(b[1])<FLT_EPSILON) ? sign_b1*FLT_EPSILON : b[1] );

        size_t ii;
        for (ii=0; ii<num; ii++)
        {
            y[ii] = b[0] * exp( -1 * x[ii] * rb);
        }
    }
}
// ===== End: toolboxes/operators/cpu/twoParaExpDecayOperator.h =====


// ===== Begin: toolboxes/operators/cpu/twoParaExpRecoveryOperator.h =====
/** \file twoParaExpRecoveryOperator.h
    \brief Implement two parameter exponential recovery operator. e.g. for T1 recovery
    \author     Hui Xue
*/



namespace Gadgetron {

    // y = bi[0] -  bi[0]* exp(-x/bi[1])

    template <class ARRAY> class twoParaExpRecoveryOperator : public curveFittingOperator<ARRAY>
    {
    public:

        typedef curveFittingOperator<ARRAY> BaseClass;
        typedef typename BaseClass::ELEMENT_TYPE ELEMENT_TYPE;
        typedef typename BaseClass::REAL REAL;

        twoParaExpRecoveryOperator();
        virtual ~twoParaExpRecoveryOperator();

        virtual void gradient(const ELEMENT_TYPE& xi, const ARRAY& b, ARRAY& grad);
        virtual void magnitude(const ARRAY& x, const ARRAY& b, ARRAY& y);

    protected:
    };

    template <class ARRAY>
    twoParaExpRecoveryOperator<ARRAY>::twoParaExpRecoveryOperator() : BaseClass()
    {
    }

    template <class ARRAY>
    twoParaExpRecoveryOperator<ARRAY>::~twoParaExpRecoveryOperator()
    {
    }

    template <class ARRAY>
    void twoParaExpRecoveryOperator<ARRAY>::gradient(const ELEMENT_TYPE& xi, const ARRAY& b, ARRAY& grad)
    {
        try
        {
            size_t num = b.size();
            if(grad.size()!=num) grad.resize(num, 0);

            int sign_b1 = boost::math::sign(b[1]);
            ELEMENT_TYPE rb = 1.0 / ( (std::abs(b[1])<FLT_EPSILON) ? sign_b1*FLT_EPSILON : b[1] );

            ELEMENT_TYPE val = std::exp(-1 * xi * rb);
            grad[0] = 1 - val;
            grad[1] = -1 * b[0] * val * xi * rb * rb;
        }
        catch(...)
        {
            GADGET_THROW("Errors happened in twoParaExpRecoveryOperator<ARRAY>::gradient(...) ... ");
        }
    }

    template <class ARRAY>
    void twoParaExpRecoveryOperator<ARRAY>::magnitude(const ARRAY& x, const ARRAY& b, ARRAY& y)
    {
        size_t num = x.size();
        if(y.size()!=x.size()) y.resize(num, 0);

        int sign_b1 = boost::math::sign(b[1]);
        ELEMENT_TYPE rb = 1.0 / ( (std::abs(b[1])<FLT_EPSILON) ? sign_b1*FLT_EPSILON : b[1] );

        size_t ii;
        for (ii=0; ii<num; ii++)
        {
            y[ii] = b[0] - b[0] * exp( -1 * x[ii] * rb);
        }
    }
}
// ===== End: toolboxes/operators/cpu/twoParaExpRecoveryOperator.h =====




