    void get_current_moment(std::string& procTime)
    {
        char timestamp[100];
        time_t mytime;
        struct tm *mytm;
        mytime = time(NULL);
        mytm = localtime(&mytime);
        strftime(timestamp, sizeof(timestamp), "%a, %b %d %Y, %H:%M:%S", mytm);
        procTime = timestamp;
    }

