    template <typename T, typename R> void abs(const hoNDArray<T>& x, hoNDArray<R>& r) {
        if (r.get_number_of_elements() != x.get_number_of_elements()) {
            r.create(x.dimensions());
        }
        transform(x,r,[](auto val){return abs(val);});
    }

