                if ( DOut == 1 )
                {
                    value(0, numOfPixels) = valueTmp(0, n);
                }
                else if ( DOut == 2 )
                {
                    value(0, numOfPixels) = valueTmp(0, n);
                    value(1, numOfPixels) = valueTmp(1, n);
                }
