template <typename T> 
void compute_2d_filter(const hoNDArray<T>& fx, const hoNDArray<T>& fy, hoNDArray<T>& fxy)
{
    try
    {
        size_t RO = fx.get_size(0);
        size_t E1 = fy.get_size(0);

        fxy.create(RO, E1);
        T* pFxy = fxy.begin();

        size_t x, y;

        for (y = 0; y<E1; y++)
        {
            for (x = 0; x<RO; x++)
            {
                pFxy[y*RO + x] = fx(x) * fy(y);
            }
        }
    }
    catch (...)
    {
        GADGET_THROW("Errors in compute_2d_filter(...) ... ");
    }
}

